def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import deque
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    out = [[bg] * w for _ in range(h)]
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r,c) in seen:
                continue
            q = deque([(r,c)]); seen.add((r,c)); comp=[]
            while q:
                y,x=q.popleft(); comp.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                        seen.add((yy,xx)); q.append((yy,xx))
            if len(comp) >= 6:
                r0=min(y for y,x in comp); r1=max(y for y,x in comp)
                c0=min(x for y,x in comp); c1=max(x for y,x in comp)
                for y in range(r0,r1+1):
                    for x in range(c0,c1+1): out[y][x]=color
    return out
